import React from'react'
import TextHoverComp from './TextHoverComp';

const data = [
  {
    label: "UI Components",
    description:
      "Beautifully crafted components built for modern Next.js and React applications.",
  },
  {
    label: "Text Animations",
    description:
      "Creative headline effects, reveal animations, and smooth typography interactions.",
  },
  {
    label: "Background Effects",
    description:
      "Futuristic grids, gradients, particles, and immersive animated backgrounds.",
  },
  {
    label: "Scroll Animations",
    description:
      "Smooth scroll-triggered interactions and cinematic motion experiences.",
  },
  {
    label: "Buttons & Hover FX",
    description:
      "Premium buttons, magnetic interactions, and modern hover micro-interactions.",
  },
  {
    label: "Page Transitions",
    description:
      "Fluid route transitions and immersive navigation animations for modern apps.",
  },
  {
    label: "3D Experiences",
    description:
      "Interactive WebGL, Three.js, and motion-driven visual experiences.",
  },
  {
    label: "Creative Layouts",
    description:
      "Modern sections, bento grids, hero layouts, and showcase-ready designs.",
  },
  {
    label: "Developer Experience",
    description:
      "Reusable, customizable, and production-ready UI built for fast development.",
  },
];

const TextHover = () => {
 return (
 <>

 <div className='h-screen w-full'>
 <TextHoverComp
 data={data}
 bgColor="#0a0a0a"
 textColor="#ffffff"
 />

 </div>
 </>
 )
}

export default TextHover

"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

const CornerSVG = ({ className, style }) => (
  <svg
    className={className}
    style={style}
    width="10"
    height="10"
    viewBox="0 0 10 10"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
  >
    <path
      d="M0.499951 0.199996L0.499952 9.2M0.199951 0.499995L9.19995 0.499995"
      stroke="currentColor"
    />
  </svg>
);

const clamp = (value, min, max) => Math.min(Math.max(value, min), max);

export default function TextHoverComp({
  data = [],
  bgColor = "#0a0a0a",
  textColor = "#ffffff",
}) {
  const sectionRef = useRef(null);
  const contentRef = useRef(null);
  const listRef = useRef(null);
  const highlightRef = useRef(null);

  const itemRefs = useRef([]);
  const labelRefs = useRef([]);
  const descriptionRefs = useRef([]);

  const rafRef = useRef(null);
  const refreshStartRef = useRef(null);
  const activeIndexRef = useRef(null);

  const [activeIndex, setActiveIndex] = useState(null);
  const [isCompact, setIsCompact] = useState(false);

  const getCompact = useCallback(() => {
    if (typeof window === "undefined") return false;
    return window.innerWidth < 1025;
  }, []);

  const measureHighlight = useCallback((index) => {
    const content = contentRef.current;
    const el = itemRefs.current[index];
    const label = labelRefs.current[index];
    const description = descriptionRefs.current[index];

    if (!content || !el || !label) return null;

    const contentRect = content.getBoundingClientRect();
    const elRect = el.getBoundingClientRect();
    const labelRect = label.getBoundingClientRect();
    const descriptionRect = description?.getBoundingClientRect();

    const width = window.innerWidth;

    const isMobileViewport = width < 640;
    const isTabletViewport = width >= 640 && width < 1025;
    const isCompactViewport = width < 1025;

    const framePadding = isMobileViewport ? 30 : isTabletViewport ? 46 : 72;
    const minFrameHeight = isMobileViewport ? 82 : isTabletViewport ? 96 : 88;

    const widestRect =
      !isCompactViewport &&
      descriptionRect &&
      descriptionRect.width > labelRect.width
        ? descriptionRect
        : labelRect;

    const descriptionWidth = descriptionRect?.width || 0;
    const labelWidth = labelRect.width || 0;

    const compactMeasuredWidth =
      Math.max(labelWidth, descriptionWidth) + framePadding;

    const compactMaxWidth = isMobileViewport
      ? Math.min(contentRect.width - 34, 360)
      : Math.min(contentRect.width - 64, 580);

    const compactMinWidth = isMobileViewport ? 240 : 360;

    const frameWidth = isCompactViewport
      ? clamp(compactMeasuredWidth, compactMinWidth, compactMaxWidth)
      : widestRect.width + framePadding;

    const contentHeight = isCompactViewport
      ? Math.max(elRect.height - 18, minFrameHeight)
      : Math.max(elRect.height - 120, 0);

    const frameHeight = Math.max(contentHeight, minFrameHeight);

    const labelCenterX =
      labelRect.left - contentRect.left + labelRect.width / 2;

    const compactLeft = labelCenterX - frameWidth / 2;

    const minLeft = isMobileViewport ? 14 : 28;
    const maxLeft = contentRect.width - frameWidth - minLeft;

    const frameLeft = isCompactViewport
      ? clamp(compactLeft, minLeft, Math.max(minLeft, maxLeft))
      : widestRect.left -
        contentRect.left -
        (frameWidth - widestRect.width) / 2;

    const frameTop = isCompactViewport
      ? elRect.top - contentRect.top + (isMobileViewport ? 8 : 10)
      : elRect.top -
        contentRect.top +
        30 -
        (frameHeight - contentHeight) / 2;

    return {
      width: frameWidth,
      height: frameHeight + (isCompactViewport ? 22 : 60),
      x: frameLeft,
      y: frameTop,
    };
  }, []);

  const moveHighlight = useCallback(
    (index, instant = false) => {
      const highlight = highlightRef.current;
      const next = measureHighlight(index);

      if (!highlight || !next) return;

      gsap.to(highlight, {
        width: next.width,
        height: next.height,
        x: next.x,
        y: next.y,
        opacity: 1,
        scale: 1,
        filter: "blur(0px)",
        duration: instant ? 0.22 : 0.35,
        ease: "power3.out",
        overwrite: "auto",
      });
    },
    [measureHighlight]
  );

  const startRefreshTracking = useCallback(
    (index) => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
        rafRef.current = null;
      }

      refreshStartRef.current = performance.now();

      const tick = () => {
        if (activeIndexRef.current !== index) return;

        moveHighlight(index, true);

        const elapsed = performance.now() - refreshStartRef.current;

        if (elapsed < 520) {
          rafRef.current = requestAnimationFrame(tick);
        } else {
          rafRef.current = null;
        }
      };

      rafRef.current = requestAnimationFrame(tick);
    },
    [moveHighlight]
  );

  const setActive = useCallback(
    (index) => {
      activeIndexRef.current = index;
      setActiveIndex(index);

      requestAnimationFrame(() => {
        moveHighlight(index, false);
        startRefreshTracking(index);
      });
    },
    [moveHighlight, startRefreshTracking]
  );

  const clearActive = useCallback(() => {
    activeIndexRef.current = null;
    setActiveIndex(null);

    if (rafRef.current) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }

    if (highlightRef.current) {
      gsap.to(highlightRef.current, {
        opacity: 0,
        scale: 1.14,
        filter: "blur(8px)",
        duration: 0.2,
        ease: "power3.out",
        overwrite: "auto",
      });
    }
  }, []);

  const handleDesktopHover = useCallback(
    (index) => {
      if (!isCompact) {
        setActive(index);
      }
    },
    [isCompact, setActive]
  );

  const handleDesktopLeave = useCallback(() => {
    if (!isCompact) {
      clearActive();
    }
  }, [isCompact, clearActive]);

  const handleItemClick = useCallback(
    (index) => {
      if (!isCompact) return;

      if (activeIndexRef.current === index) {
        clearActive();
      } else {
        setActive(index);
      }
    },
    [isCompact, clearActive, setActive]
  );

  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.fromTo(
        contentRef.current,
        {
          opacity: 0,
          y: 80,
        },
        {
          opacity: 1,
          y: 0,
          duration: 1.2,
          ease: "power4.inOut",
          scrollTrigger: {
            trigger: sectionRef.current,
            start: "top 60%",
          },
        }
      );
    }, sectionRef);

    return () => ctx.revert();
  }, []);

  useEffect(() => {
    const frame = requestAnimationFrame(() => {
      const compact = getCompact();

      setIsCompact(compact);
      setActiveIndex(null);
      activeIndexRef.current = null;
    });

    const onResize = () => {
      const compact = getCompact();

      setIsCompact(compact);
      setActiveIndex(null);
      activeIndexRef.current = null;

      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
        rafRef.current = null;
      }

      if (highlightRef.current) {
        gsap.set(highlightRef.current, {
          opacity: 0,
          scale: 1.14,
          filter: "blur(8px)",
        });
      }
    };

    window.addEventListener("resize", onResize);

    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("resize", onResize);
    };
  }, [getCompact]);

  useEffect(() => {
    if (!highlightRef.current) return;

    gsap.set(highlightRef.current, {
      width: 0,
      height: 0,
      x: 0,
      y: 0,
      opacity: 0,
      scale: 1.14,
      filter: "blur(8px)",
      transformOrigin: "center center",
      willChange: "transform,width,height,opacity,filter",
    });
  }, []);

  useEffect(() => {
    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, []);

  return (
    <section
      ref={sectionRef}
      className="relative min-h-dvh overflow-hidden py-12 max-md:py-20 max-sm:py-16"
      style={{ backgroundColor: bgColor }}
    >
      <div className="pointer-events-none absolute inset-0 overflow-hidden max-md:hidden">
        <div className="absolute left-1/2 top-1/2 h-150 w-150 -translate-x-1/2 -translate-y-1/2 rounded-full bg-indigo-900/10 blur-[120px]" />
      </div>

      <div
        ref={contentRef}
        className="container relative mx-auto px-4 max-md:px-8 max-sm:px-5"
        style={{ opacity: 0, transform: "translateY(80px)" }}
      >
        <div className="relative">
          <ul
            ref={listRef}
            className="relative isolate flex flex-col items-center text-center"
          >
            {data.map((item, i) => {
              const isActive = activeIndex === i;

              return (
                <li
                  key={item.label}
                  ref={(el) => {
                    itemRefs.current[i] = el;
                  }}
                  className={[
                    "group grid w-full text-center",
                    "px-10 max-md:px-6 max-sm:px-2",
                    "transition-[padding,grid-template-rows] duration-500",
                    isActive
                      ? "grid-rows-[auto_1fr] py-5 max-md:py-7 max-sm:py-8"
                      : "grid-rows-[auto_0fr] py-5 max-md:py-7 max-sm:py-8",
                  ].join(" ")}
                  onMouseEnter={() => handleDesktopHover(i)}
                  onMouseLeave={handleDesktopLeave}
                  onClick={() => handleItemClick(i)}
                >
                  <button
                    type="button"
                    className={[
                      "relative isolate flex w-full justify-center overflow-hidden focus:outline-none",
                      isCompact ? "cursor-pointer" : "cursor-default",
                    ].join(" ")}
                    aria-expanded={isActive}
                    aria-controls={`industry-content-${i}`}
                    onClick={(event) => {
                      event.stopPropagation();
                      handleItemClick(i);
                    }}
                  >
                    <span
                      ref={(el) => {
                        labelRefs.current[i] = el;
                      }}
                      className="grid max-w-full text-center"
                    >
                      <h3
                        className={[
                          "col-start-1 row-start-1 font-mono uppercase leading-none tracking-widest",
                          "text-2xl max-md:text-[4vw] max-sm:text-[4.5vw]",
                          "text-neutral-400",
                          "transition-transform duration-500",
                          isActive ? "-translate-y-full" : "translate-y-0",
                        ].join(" ")}
                      >
                        {item.label}
                      </h3>

                      <span
                        aria-hidden="true"
                        className={[
                          "col-start-1 row-start-1 font-mono uppercase leading-none tracking-widest",
                          "text-3xl max-md:text-[4.8vw] max-sm:text-[6vw]",
                          "transition-transform duration-500",
                          isActive ? "translate-y-0" : "translate-y-full",
                        ].join(" ")}
                        style={{ color: textColor }}
                      >
                        {item.label}
                      </span>
                    </span>
                  </button>

                  <div
                    id={`industry-content-${i}`}
                    className="mx-auto flex w-[70%] justify-center overflow-hidden max-md:w-[82%] max-sm:w-full"
                  >
                    <p
                      ref={(el) => {
                        descriptionRefs.current[i] = el;
                      }}
                      className="max-w-107.5 pt-1 text-center text-md font-light leading-relaxed tracking-wide text-neutral-400 max-md:max-w-[64vw] max-md:text-[2.5vw] max-sm:max-w-[72vw] max-sm:pt-4 max-sm:text-[4vw]"
                    >
                      {item.description}
                    </p>
                  </div>
                </li>
              );
            })}
          </ul>

          <div
            ref={highlightRef}
            className="pointer-events-none absolute left-[-1%] top-0 max-md:left-[-5%]"
          >
            <CornerSVG
              className="absolute left-0 top-0 size-8 opacity-70 max-md:size-7 max-sm:size-5"
              style={{ color: textColor }}
            />
            <CornerSVG
              className="absolute right-0 top-0 size-8 rotate-90 opacity-70 max-md:size-7 max-sm:size-5"
              style={{ color: textColor }}
            />
            <CornerSVG
              className="absolute bottom-3 left-0 size-8 -rotate-90 opacity-70 max-md:size-7 max-md:bottom-2 max-sm:size-5"
              style={{ color: textColor }}
            />
            <CornerSVG
              className="absolute bottom-3 right-0 size-8 rotate-180 opacity-70 max-md:size-7 max-md:bottom-2 max-sm:size-5"
              style={{ color: textColor }}
            />
          </div>
        </div>
      </div>
    </section>
  );
}
